export const PROJECTS=['rates-v1','operations-fractions-decimals-v1','earning-money-v1','length-v1','area-circles-sectors-v1','area-parallelograms-triangles-v1','logarithms-v1'];
function splitHeadings(p,b,left,right){const root=b.content,parts=root.children;const lh=find(parts[0],left),rh=find(parts[1],right);for(const part of parts.slice(0,2)){const old=part.prompt.blocks;part.prompt.blocks=old.filter(x=>x!==lh&&x!==rh);for(const response of b.sourceReview?.responses??[]){const binding=response.promptBinding;if(binding?.ownerId!==part.id)continue;const match=binding.path?.match(/^\/prompt\/blocks\/(\d+)(\/.*)?$/);if(!match)continue;const kept=old[Number(match[1])],index=part.prompt.blocks.indexOf(kept);if(index<0)throw Error('Response binds to removed heading: '+response.targetId);binding.path='/prompt/blocks/'+index+(match[2]??'');}}const h=heading(b.id+'-headings');h.rows[0][0].blocks=[lh];h.rows[0][1].blocks=[rh];paired(p,b,parts,h,root.prompt?.blocks??[]);}
export function repairPairedPreset(source){return transform(source,'paired-preset',p=>{
 if(p.id==='rates-v1'){
  let b=block(p,'p36-example-group');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)'))){const r=b.content,hs=r.prompt.blocks[0],tables=r.prompt.blocks.slice(1);if(tables.length!==3)throw Error('Rates p36 changed');const parts=tables.flatMap((t,i)=>[partFromCell(t.id,{blocks:t.rows.flat().flatMap(c=>c.blocks)}),r.children[i]]);retire(b,tables.flatMap(t=>[t.id,...t.rows.flat().map(c=>c.id)]));paired(p,b,parts,hs);}
  b=block(p,'p56-example-block');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)'))){const root=b.content,turn=root.children[0],lh=root.prompt.blocks.shift(),rh=turn.prompt.blocks.shift(),h=heading('p56-paired-headings');h.rows[0][0].blocks=[lh];h.rows[0][1].blocks=[rh];paired(p,b,[{id:'p56-worked-example-part',type:'part',label:'',prompt:root.prompt,answerSpaceMm:0},turn],h);}
  b=block(p,'p57-related-rates-drip-row');const second=block(p,'p57-related-rates-coffee-fuel-row');if(second){const pair=row=>{const n=row.content,items=n.prompt.blocks,cut=items.findIndex(x=>/turn-heading/.test(x.id));const left=items[0],right=items[cut];return {left,right,parts:[{id:items[1].id+'-part',type:'part',label:'',prompt:doc(items.slice(1,cut)),answerSpaceMm:0},{...n,type:'part',prompt:doc(items.slice(cut+1))}]};};const a=pair(b),c=pair(second),h=heading('p57-paired-headings');h.rows[0][0].blocks=[a.left];h.rows[0][1].blocks=[a.right];retire(b,[second.id,c.left.id,c.right.id]);b.sourceRefs=[...(b.sourceRefs??[]),...(second.sourceRefs??[])];b.sourceReview.responses=[...(b.sourceReview.responses??[]),...(second.sourceReview.responses??[])];b.sourceReview.workingSpaceEstimate.estimates.push(...second.sourceReview.workingSpaceEstimate.estimates);paired(p,b,[...a.parts,...c.parts],h);b.content.id='p57-related-rates-paired-root';clearArrangement(p,second,b);const s=p.sections.find(s=>s.blocks.includes(second));s.blocks.splice(s.blocks.indexOf(second),1);}
 }
 if(p.id==='operations-fractions-decimals-v1')for(const id of ['p28-q4','p85-algorithm-pair']){const b=block(p,id);if(b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)')))continue;const turn=b.content.children[0],t=turn.prompt.blocks[0];let h,left,right;
  if(id==='p28-q4'){h={...t,rows:[t.rows[0]],border:false};delete h.rowHeights;delete h.widthMm;left=t.rows[1][0];right=t.rows[1][1];retire(b,[left.id,right.id]);const rp=doc(right.blocks);delete rp.blocks[0].spaceAfter;turn.prompt=rp;turn.answerSpaceMm=58;delete turn.responseSpace;retire(b,[t.id]);paired(p,b,[partFromCell('p28-q4-worked-part',left),turn],h);}
  else {left=t.rows[0][0];right=t.rows[0][1];h=heading('p85-paired-headings','Worked Solution');for(const [cell,i]of [[left,0],[right,1]]){const first=cell.blocks[0],title=first.inlines[0];h.rows[0][i].blocks[0].inlines=[title];first.inlines=first.inlines.slice(2);}turn.prompt=doc(right.blocks);retire(b,[t.id,right.id]);paired(p,b,[partFromCell(left.id,left),turn],h);}
 }
 if(p.id==='earning-money-v1'){
  let b=block(p,'p50-example-block');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)'))){const root=b.content,rows=root.children.slice(0,3),tail=root.children.slice(3),extra=rows[0].prompt.blocks.filter(x=>x.type!=='table'),h=rows[0].prompt.blocks.find(x=>x.type==='table');const parts=rows.flatMap(r=>{retire(b,[r.id]);r.children[0].label=r.label;return r.children;});paired(p,b,parts,h,extra);if(tail.length){const follow={...structuredClone(b),id:'p50-example-reflections',content:{id:'p50-example-reflections-root',type:'group',label:'',children:tail}};delete follow.sourceReview.layoutRepairProvenance;follow.sourceReview.responses=(b.sourceReview.responses??[]).filter(r=>tail.some(t=>t.id===r.targetId));b.sourceReview.responses=(b.sourceReview.responses??[]).filter(r=>!tail.some(t=>t.id===r.targetId));follow.sourceReview.workingSpaceEstimate={method:'solution-steps',estimates:[]};const s=p.sections.find(s=>s.blocks.includes(b));s.blocks.splice(s.blocks.indexOf(b)+1,0,follow);}}
  b=block(p,'p66-example-group');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)')))splitHeadings(p,b,'p66-joy-column-heading','p66-patrick-column-heading');
 }
 if(p.id==='area-circles-sectors-v1'){const b=block(p,'p23-radius-example-group');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)')))splitHeadings(p,b,'p23-radius-example-column-heading','p23-radius-your-turn-column-heading');}
 if(p.id==='length-v1'){const b=block(p,'p45-diameter-turn-block');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)'))){splitHeadings(p,b,'p45-worked-example-column-heading','p45-your-turn-column-heading');b.content.children[0].diagramPlacement='right-of-prompt';p.settings.layoutOverrides.blockLayouts['p45-diameter-example']={...p.settings.layoutOverrides.blockLayouts['p45-diameter-example'],textWidthMm:55};b.sourceReview.customArrangement={reason:'Diameter figure remains beside the formula/substitution demonstration to identify the unknown used in the working.'};}}
 if(p.id==='area-parallelograms-triangles-v1'){const b=block(p,'p43-side-length-activity');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)'))){const h=b.content.prompt.blocks[0];paired(p,b,b.content.children,h);for(const part of b.content.children)if(part.questionDiagrams?.length){part.afterDiagramPrompt=doc(part.prompt.blocks.splice(1));delete part.diagramPlacement;}b.sourceReview.customArrangement={reason:'Each supplied figure stays between its own task and its corresponding calculation/scaffold, preserving the mathematical association in both paired columns.'};}}
 if(p.id==='logarithms-v1'){const b=block(p,'p27-q22');if(!b.sourceReview?.intentionalDepartures?.some(s=>String(s).includes('(paired-preset)'))){const root=b.content,t=root.prompt.blocks.find(x=>x.type==='table'),turn=root.children[0],h={...t,rows:[t.rows[0]],border:false};delete h.widthMm;delete h.rowHeights;const left=t.rows[1][0],right=t.rows[1][1];turn.prompt=doc([{id:t.id+'-response',type:'table',widths:[1],padding:t.padding,border:false,rowHeights:[t.rowHeights[1]],rows:[[right]]}]);const estimate=b.sourceReview.workingSpaceEstimate?.estimates?.find(x=>x.targetId===turn.id);turn.answerSpaceMm=estimate?.answerSpaceMm??0;turn.responseSpace='scaffold';for(const x of right.blocks)delete x.spaceAfter;retire(b,[left.id,right.id]);paired(p,b,[partFromCell('p27-q22-worked-part',left),turn],h,root.prompt.blocks.filter(x=>x!==t));}}
});}
await dryRunMain(import.meta.url,repairPairedPreset,PROJECTS);
